PREFIX rda: <http://rdvocab.info/RDARelationshipsWEMI/>
PREFIX dcterms: <http://purl.org/dc/terms/>
SELECT DISTINCT ?edition ?title ?gallica WHERE {
 ?edition rda:electronicReproduction ?gallica ; dcterms:title ?title .
 FILTER (STRSTARTS(STR(?gallica), "https://gallica.bnf.fr/ark:/12148/") || STRSTARTS(STR(?gallica), "http://gallica.bnf.fr/ark:/12148/"))
} LIMIT 15
